css:
.lv-paper {
	font-family: Arial, Helvetica, sans-serif;
	color: #111;
	font-size: 9pt;
	line-height: 1.25;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.lv-page-2 {
	page-break-before: always;
	padding-top: 4px;
}

.lv-brand {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 6px;
}
.lv-brand td {
	vertical-align: middle;
	border: 0;
	padding: 0;
}
.lv-brand-left { width: 78px; }
.lv-brand-right { width: 110px; text-align: right; }
.lv-brand-mid { text-align: center; }

.lv-hse {
	width: 62px;
	height: 62px;
	border: 3px solid #0a3d91;
	background: #0a3d91;
	color: #fff;
	text-align: center;
	box-sizing: border-box;
}
.lv-hse-pct {
	font-size: 12px;
	font-weight: 700;
	padding-top: 10px;
}
.lv-hse-txt {
	font-size: 17px;
	font-weight: 800;
	letter-spacing: 0.06em;
}

.lv-adnoc { text-align: right; }
.lv-adnoc-logo {
	max-height: 58px;
	max-width: 100px;
	display: inline-block;
}

.lv-title {
	text-align: center;
	font-size: 16pt;
	font-weight: 800;
	letter-spacing: 0.01em;
	text-transform: uppercase;
	line-height: 1.15;
	margin: 2px 0 0;
}
.lv-title-orange { color: #e86a17; }
.lv-title-blue { color: #0a3d91; }
.lv-subtitle {
	text-align: center;
	color: #e86a17;
	font-size: 11pt;
	font-weight: 700;
	margin: 3px 0 8px;
}

.lv-meta {
	width: 100%;
	border-collapse: collapse;
	margin: 0 0 8px;
	table-layout: fixed;
}
.lv-meta td {
	border: 1px solid #8c9aab;
	padding: 5px 7px;
	vertical-align: middle;
	height: 20px;
}
.lv-meta-label {
	width: 18%;
	background: #0a3d91;
	color: #fff;
	font-weight: 700;
	font-size: 8.5pt;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.lv-meta-value {
	width: 32%;
	background: #fff;
	font-weight: 600;
}

.lv-grid {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}
.lv-grid th,
.lv-grid td {
	border: 1px solid #8c9aab;
	vertical-align: top;
}
.lv-unit {
	background: #e86a17;
	color: #fff;
	font-weight: 800;
	font-size: 10pt;
	text-align: center;
	padding: 6px 8px;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.lv-th-outcome,
.lv-th-criteria,
.lv-th-source {
	background: #0a3d91;
	color: #fff;
	font-weight: 800;
	font-size: 8.5pt;
	text-align: center;
	padding: 5px 4px;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.lv-th-outcome { width: 8%; }
.lv-th-criteria { width: 77%; }
.lv-th-source { width: 15%; }

.lv-outcome {
	background: #0a3d91;
	color: #fff;
	width: 8%;
	text-align: center;
	vertical-align: middle;
	padding: 4px 2px;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.lv-outcome-text {
	display: inline-block;
	-webkit-transform: rotate(-90deg);
	transform: rotate(-90deg);
	white-space: nowrap;
	font-size: 8.5pt;
	font-weight: 700;
	width: 160px;
	margin-left: -62px;
}

.lv-criterion {
	padding: 3px 6px 3px 8px;
	background: #fff;
}
.lv-num {
	color: #e86a17;
	font-weight: 800;
	margin-right: 6px;
}
.lv-source {
	text-align: center;
	vertical-align: middle;
	padding: 3px 4px;
}
.lv-box { font-size: 12px; }
.lv-src-letter {
	display: block;
	font-size: 8pt;
	font-weight: 700;
	color: #0a3d91;
}

.lv-guide-label {
	width: 8%;
	background: #0a3d91;
	color: #fff;
	font-weight: 800;
	font-size: 8pt;
	padding: 8px 6px;
	vertical-align: middle !important;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.lv-guide-text {
	padding: 7px 8px;
	font-size: 8pt;
	background: #fff;
	vertical-align: middle !important;
}

.lv-company-footer {
	margin-top: 10px;
	padding-top: 6px;
	border-top: 1.5px solid #0a3d91;
	text-align: right;
	color: #0a3d91;
	font-weight: 700;
	font-size: 9pt;
}

.lv-line-block { margin: 14px 0 10px; }
.lv-line-label {
	color: #0a3d91;
	font-weight: 700;
	font-size: 10pt;
	margin-bottom: 4px;
}
.lv-line-fill {
	min-height: 18px;
	border-bottom: 1.5px solid #0a3d91;
	padding: 2px 2px 4px;
	font-size: 10pt;
}
.lv-line-fill-tall {
	min-height: 72px;
	border-bottom: 1.5px solid #0a3d91;
}

.lv-evidence-bar {
	background: #d9d9d9;
	text-align: center;
	padding: 7px 8px;
	margin: 16px 0;
	font-size: 9pt;
	font-weight: 600;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.lv-declaration {
	margin: 22px 0 18px;
	font-size: 9.5pt;
	line-height: 1.45;
	text-align: left;
}
.lv-del {
	text-decoration: line-through;
	color: #555;
}
.lv-del-note {
	margin-top: 8px;
	font-size: 8.5pt;
	font-style: italic;
}

.lv-assessor {
	width: 100%;
	border-collapse: collapse;
	margin-top: 8px;
}
.lv-assessor th {
	background: #e86a17;
	color: #fff;
	font-weight: 800;
	font-size: 10pt;
	padding: 7px 8px;
	border: 1px solid #c4530f;
	text-align: center;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.lv-assessor td {
	border: 1px solid #8c9aab;
	height: 58px;
	padding: 6px 8px;
	vertical-align: middle;
	text-align: center;
	width: 33.33%;
}
.lv-sign { max-height: 46px; max-width: 150px; }
